const t = await tools.browser.tabs.open({ url: "https://www.youtube.com/watch?v=JGwWNGJdvx8", focus: true });
await new Promise(r => setTimeout(r, 4000));
const res = await tools.browser.evaluate({
  tabID: t.id,
  script: `(() => {
    const pr = window.ytInitialPlayerResponse || (document.querySelector('ytd-app') && null);
    if (!pr) return { ok: false };
    const spec = pr.storyboards && pr.storyboards.playerStoryboardSpecRenderer && pr.storyboards.playerStoryboardSpecRenderer.spec;
    return { ok: true, title: pr.videoDetails && pr.videoDetails.title, len: pr.videoDetails && pr.videoDetails.lengthSeconds, spec: spec || null };
  })()`
});
res

